import { api } from "../bridge";

/** A patient in a doctor's live queue, in calling order (the patient in consultation first). */
export interface DoctorQueueEntryOut {
  queue_id: number;
  ticket_id: number;
  ticket_number: string;
  patient_id: number;
  mrn: string;
  patient_name: string;
  gender: "male" | "female" | "other" | "unknown" | null;
  age_years: number | null;
  dob: string | null;
  token_no: number;
  token_date: string;
  priority: number;
  queue_status:
    | "Active"
    | "Suspended"
    | "Deferred"
    | "Rerouted"
    | "Completed"
    | "Cancelled"
    | "Expired";
  ticket_status:
    | "Issued"
    | "Waiting"
    | "InConsultation"
    | "Examined"
    | "Completed"
    | "Deferred"
    | "Expired"
    | "Forfeited"
    | "Refunded"
    | "Void"
    | "Cancelled";
  payment_status:
    | "Unpaid"
    | "PartiallyPaid"
    | "Paid"
    | "CreditAuthorized"
    | "Waivered"
    | "Refunded"
    | "PanelBilled";
  approval_lock: "None" | "RefundPending" | "WaiverPending" | "CreditPending";
  queued_at: string;
  called_at: string | null;
  rerouted_from_queue_id: number | null;
  is_rerouted: boolean;
  reroute_reason: string | null;
  queue_group: string;
  waiting_minutes: number;
}

